#!/usr/bin/env bash
# ============================================================
#  DAC - Decentralized Autonomous Coder
#  Self-contained installer for Termux (any device)
#  Usage:  bash install-dac.sh [YOUR_API_KEY] [MODEL]
# ============================================================
set -euo pipefail

API_KEY="${1:-}"
MODEL="${2:-gpt-4o}"
DEST_DIR="${HOME}/NEXTGENWORLD+HUMAN_AI"

echo
echo "DAC - Decentralized Autonomous Coder Installer"
echo "Target: ${DEST_DIR}"
echo

# ---------- Package manager detection ----------
echo "[1/6] Checking package manager..."
if command -v pkg >/dev/null 2>&1; then
    PM="pkg"
elif command -v apt-get >/dev/null 2>&1; then
    PM="apt"
else
    echo "ERROR: No package manager found (need pkg or apt)."
    exit 1
fi
echo "  Using: ${PM}"

# ---------- Install dependencies ----------
echo "[2/6] Installing python, git, tmux..."
if [ "${PM}" = "pkg" ]; then
    pkg update -y
    pkg install -y python git tmux || true
else
    apt-get update -y
    apt-get install -y python3 python3-pip git tmux || true
fi

# ---------- Create project structure ----------
echo "[3/6] Creating project structure at ${DEST_DIR}..."
mkdir -p "${DEST_DIR}/dac/core" "${DEST_DIR}/dac/commands"

# ---------- Write all DAC source files ----------
echo "[4/6] Writing DAC source files..."

echo 'IiIiRGVjZW50cmFsaXplZCBBdXRvbm9tb3VzIENvZGVyIChEQUMpIOKAlCBBSS1wb3dlcmVkIGNvZGluZyBmcm9tIHlvdXIgcGhvbmUuIiIiCl9fdmVyc2lvbl9fID0gIjEuMC4wIgo=' | base64 -d > "${DEST_DIR}/dac/__init__.py"
echo 'IiIiQWxsb3cgcnVubmluZyBhcyBgcHl0aG9uIC1tIGRhY2AuIiIiCmZyb20gZGFjLmxhdW5jaGVyIGltcG9ydCBtYWluCmlmIF9fbmFtZV9fID09ICJfX21haW5fXyI6CiAgICBtYWluKCkK' | base64 -d > "${DEST_DIR}/dac/__main__.py"
echo '' | base64 -d > "${DEST_DIR}/dac/cli.py"
echo 'IiIiREFDIGNvbW1hbmQgbW9kdWxlcy4iIiIK' | base64 -d > "${DEST_DIR}/dac/commands/__init__.py"
echo '' | base64 -d > "${DEST_DIR}/dac/config.py"
echo 'IiIiREFDIGNvcmUgZW5naW5lIG1vZHVsZXMuIiIiCg==' | base64 -d > "${DEST_DIR}/dac/core/__init__.py"
echo '' | base64 -d > "${DEST_DIR}/dac/core/autonomous.py"
echo '' | base64 -d > "${DEST_DIR}/dac/core/executor.py"
echo '' | base64 -d > "${DEST_DIR}/dac/core/llm.py"
echo '' | base64 -d > "${DEST_DIR}/dac/core/session.py"
echo '' | base64 -d > "${DEST_DIR}/dac/daemon.py"
echo '' | base64 -d > "${DEST_DIR}/dac/launcher.py"
echo '' | base64 -d > "${DEST_DIR}/dac/orchestrator.py"
echo '' | base64 -d > "${DEST_DIR}/dac/repl.py"
echo '' | base64 -d > "${DEST_DIR}/setup.py"
echo '' | base64 -d > "${DEST_DIR}/README.md"

# ---------- Install package ----------
echo "[5/6] Installing DAC globally..."
cd "${DEST_DIR}"
PIP_FLAGS=""
if [ "${PM}" = "apt" ]; then
    PIP_FLAGS="--break-system-packages"
fi
python3 -m pip install ${PIP_FLAGS} -e . || python3 -m pip install ${PIP_FLAGS} .

# ---------- Configure ----------
echo "[6/6] Configuring..."
if [ -n "${API_KEY}" ]; then
    python3 - << 'PYEOF'
from dac.config import load_config, save_config
cfg = load_config()
cfg['api_key'] = '${API_KEY}'
cfg['model'] = '${MODEL}'
save_config(cfg)
print('API key configured.')
PYEOF
fi

# ---------- Smoke test ----------
echo "Running smoke test..."
if dac run 'print("DAC installed OK")'; then
    echo
    echo "DAC installed successfully!"
    echo
    echo "Next steps:"
    echo "   dac device                    # check your phone"
    echo "   dac quick \"your task\"         # AI generates + executes"
    echo "   dac daemon start              # background task runner"
    echo "   dac repl                      # interactive session"
    echo
else
    echo "WARNING: Install completed but smoke test failed."
fi

